"""`stellar_seed` fixture builders and the vector helper (task 6.3).

A complete seed exists only while a test runs. The committed bytes are a fixed 32-byte pattern,
not a key, and the Base32 candidate is computed here from the documented version byte and
CRC16-XMODEM rule, so this repository never holds a live-looking seed (`AGENTS.md` 4).
"""

from __future__ import annotations

import base64

from airlock.strkey import SEED_VERSION, crc16_xmodem

from . import Case, File, Fixture

#: The path a tracked secret usually lands in. `.env` has no source suffix, so it resolves to
#: `other`, which the rule covers.
CASE_PATH = ".env"

#: A deterministic 32-byte seed body. Not a secret: the same bytes are generated by the test.
SEED_BODY = bytes(range(32))


def encode_seed(
    seed: bytes = SEED_BODY,
    *,
    version: int = SEED_VERSION,
    checksum: int | None = None,
) -> str:
    """Build a 56-character Base32 candidate from the byte contract in ARCHITECTURE.md 9.4."""
    body = bytes([version]) + seed
    value = crc16_xmodem(body) if checksum is None else checksum
    return base64.b32encode(body + value.to_bytes(2, "little")).decode("ascii")


def stellar_seed() -> Fixture:
    valid = encode_seed()
    # A canonical encoding whose checksum does not belong to the bytes before it. It looks like a
    # seed and decodes to 35 bytes, so only the checksum step can reject it.
    body = bytes([SEED_VERSION]) + SEED_BODY
    invalid = encode_seed(checksum=(crc16_xmodem(body) + 1) & 0xFFFF)
    return Fixture(
        positive=Case(files=(File(CASE_PATH, text=f"STELLAR_SECRET={valid}\n"),)),
        negative=Case(files=(File(CASE_PATH, text=f"STELLAR_SECRET={invalid}\n"),)),
    )


BUILDERS = {"stellar_seed": stellar_seed}
